CREATE TABLE IF NOT EXISTS governed_crawl_jobs(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,idempotency_key TEXT NOT NULL,created_by TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('approved','paused','completed','failed','cancelled')),plan JSONB NOT NULL,plan_digest CHAR(64) NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,idempotency_key));
CREATE TABLE IF NOT EXISTS governed_crawl_records(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,job_id TEXT NOT NULL REFERENCES governed_crawl_jobs(id),canonical_url TEXT NOT NULL,data JSONB NOT NULL,content_digest CHAR(64) NOT NULL,source_observed_at TIMESTAMPTZ NOT NULL,collected_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),UNIQUE(tenant_id,job_id,canonical_url,content_digest));
CREATE TABLE IF NOT EXISTS governed_crawl_events(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,job_id TEXT NOT NULL REFERENCES governed_crawl_jobs(id),actor_id TEXT NOT NULL,event_type TEXT NOT NULL,detail JSONB NOT NULL DEFAULT '{}',occurred_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS governed_crawl_events_lookup ON governed_crawl_events(tenant_id,job_id,occurred_at);
CREATE OR REPLACE FUNCTION reject_governed_crawl_event_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'governed crawl events are append-only'; END $$;
DROP TRIGGER IF EXISTS governed_crawl_events_append_only ON governed_crawl_events;
CREATE TRIGGER governed_crawl_events_append_only BEFORE UPDATE OR DELETE ON governed_crawl_events FOR EACH ROW EXECUTE FUNCTION reject_governed_crawl_event_mutation();
